class DictionarySerializerTest(SerializerTest):

    def setUp(self):
        super(DictionarySerializerTest, self).setUp()
        self.serializer = DictionarySerializer()
        self.return_type = dict

    def _compare_results(self, item1, item2,
                         exclude_dynamic=False,
                         exclude_items=None):
        exclude_items = exclude_items if exclude_items is not None else []
        if exclude_dynamic:
            if 'last_state_change' not in exclude_items:
                exclude_items.append('last_state_change')
            if 'last_task' not in exclude_items:
                exclude_items.append('last_task')
            if uuid.UUID not in exclude_items:
                exclude_items.append(uuid.UUID)
        if type(item1) in exclude_items:
            return

        if isinstance(item1, dict):
            self.assertIsInstance(item2, dict)
            for key, value in list(item1.items()):
                self.assertIn(key, item2)
                if key in exclude_items:
                    continue
                self._compare_results(value, item2[key],
                                      exclude_dynamic=exclude_dynamic,
                                      exclude_items=exclude_items)
            for key in item2:
                self.assertIn(key, item1)

        elif isinstance(item1, list):
            msg = "item is not a list (is a " + str(type(item2)) + ")"
            self.assertIsInstance(item2, list, msg)
            msg = "list lengths differ: {} vs {}".format(
                len(item1), len(item2))
            self.assertEqual(len(item1), len(item2), msg)
            for i, listitem in enumerate(item1):
                self._compare_results(listitem, item2[i],
                                      exclude_dynamic=exclude_dynamic,
                                      exclude_items=exclude_items)

        elif isinstance(item1, Workflow):
            raise Exception("Item is a Workflow")

        else:
            msg = "{}: types differ: {} vs {}".format(
                str(item2), type(item1), type(item2))
            self.assertEqual(type(item1), type(item2), msg)
            self.assertEqual(item1, item2)


def suite():
    return unittest.defaultTestLoader.loadTestsFromTestCase(DictionarySerializerTest)
if __name__ == '__main__':
    unittest.TextTestRunner(verbosity=2).run(suite())

class Sprite(object):

    def __init__(self, xPos, yPos):
        self.x = xPos
        self.y = yPos
        self.th = 32
        self.tw = 32

    def checkCollision(self, otherSprite):
        if (self.x < otherSprite.x + otherSprite.tw and otherSprite.x < self.x + self.tw
            and self.y < otherSprite.y + otherSprite.th and otherSprite.y < self.y + self.th):
            return True
        else:
            return False

class Actor(Sprite):

    def __init__(self, xPos, yPos):
        super(Actor, self).__init__(xPos, yPos)
        self.speed = 5
        self.dy = 0
        self.d = 3
        self.dir = "right"
        # self.newdir = "right"
        self.state = "standing"
        self.walkR = []
        self.walkL = []

    def loadPics(self):
        self.standing = loadImage("gripe_stand.png")
        self.falling = loadImage("grfalling.png")
        for i in range(8):
            imageName = "gr" + str(i) + ".png"
            self.walkR.append(loadImage(imageName))
        for i in range(8):
            imageName = "gl" + str(i) + ".png"
            self.walkL.append(loadImage(imageName))

    def checkWall(self, wall):
        if wall.state == "hidden":
            if (self.x >= wall.x - self.d and
                    (self.x + 32 <= wall.x + 32 + self.d)):
                return False

    def move(self):
        if self.dir == "right":
            if self.state == "walking":
                self.im = self.walkR[frameCount % 8]
                self.dx = self.speed
            elif self.state == "standing":
                self.im = self.standing
                self.dx = 0
            elif self.state == "falling":
                self.im = self.falling
                self.dx = 0
                self.dy = 5
        elif self.dir == "left":
            if self.state == "walking":
                self.im = self.walkL[frameCount % 8]
                self.dx = -self.speed
            elif self.state == "standing":
                self.im = self.standing
                self.dx = 0
            elif self.state == "falling":
                self.im = self.falling
                self.dx = 0
                self.dy = 5
        else:
            self.dx = 0
        self.x += self.dx
        self.y += self.dy

        if self.x <= 0:
            self.x = 0
        if self.x >= 640 - self.tw:
            self.x = 640 -self.tw

    def display(self):
        image(self.im, self.x, self.y)


class Block(Sprite):

    def __init__(self, xPos, yPos):
        super(Block, self).__init__(xPos, yPos)
        self.state = "visible"

    def loadPics(self):
        self.im = loadImage("block.png")

    def display(self):
        if self.state == "visible":
            image(self.im, self.x, self.y)

